    'global.emails.guest_guest_payment_product.body' => 'Hej, <strong>{{NAME}}</strong>,<br /><br />Det här är ett officiellt e-postmeddelande som bekräftar att din beställning har genomförts. Använd nedladdningslänken nedan för att ladda ner produkten du har köpt.<br /><br /><strong>Nedladdningslänk:</strong> {{DOWNLOAD_LINK}}<br /><br />Vänliga hälsningar,<br />Teamet på {{WEBSITE_TITLE}}.',
