    'dashboard.onboarding_modal.step_1_title' => '1. Instrumentpanelen som utgångspunkt',
    'dashboard.onboarding_modal.step_1_text' => 'Instrumentpanelen är din huvudsakliga plats för att förstå FCC-systemet. Här ser du din aktivitetsöversikt, utbildningsguider, nästa steg och en översikt över vad som redan ger resultat.',
    'dashboard.onboarding_modal.step_2_title' => '2. Huvudmenyer och innehåll',
    'dashboard.onboarding_modal.step_2_text' => 'Via huvudmenyn kommer du åt innehåll från Forever Card Club, Forever-produkter, bloggen, kontaktuppgifter och kontrollpanelen. Härifrån kan du lära dig mer, dela innehåll och bygga upp din Forever-verksamhet.',
    'dashboard.onboarding_modal.step_3_title' => '3. FCC-appar och länkar',
    'dashboard.onboarding_modal.step_3_text' => 'Dina FCC-appar fungerar som din personliga digitala bas, därifrån vägleder du besökare till produkter, registreringar, kontakter och andra viktiga åtgärder.',
    'dashboard.onboarding_modal.step_4_title' => '4. Blogg och rekommendationer',
    'dashboard.onboarding_modal.step_4_text' => 'Bloggen och avsnittet Forever Products används för att dela utbildande innehåll och produktinnehåll tillsammans med din rekommendation, så att intresset för produkterna och webbshopen fortsätter att vara kopplat till dig.',
    'dashboard.onboarding_modal.step_5_title' => '5. Signal, AI och din tillväxtplan',
    'dashboard.onboarding_modal.step_5_text' => 'FCC följer vilka åtgärder som faktiskt leder till Forever-webbutiken. AI använder den informationen för att föreslå tydligare nästa steg och en bättre tillväxtplan.',
