    'dashboard.tutorials.blog_referral.category_step_1_title' => 'Du är nu i Forever Products',
    'dashboard.tutorials.blog_referral.category_step_1_text' => 'Det här är produktbloggsavsnittet med innehåll som du kan dela genom din rekommendation. Guiden tar dig nu till rätt artikel och den delbara rekommendationslänken.',
