    'dashboard.tutorials.blog_referral.category_step_2_text' => 'Om du redan vet vilken produkt du vill skicka skriver du in den i sökfältet. Det är det snabbaste sättet att hitta artikeln som motsvarar personens intresse.',
    'dashboard.tutorials.blog_referral.category_step_3_title' => 'Öppna produktartikeln',
