    'dashboard.tutorials.blog_referral.article_step_1_text' => 'Överst i artikeln ser du delningsraden med din rekommendation. När du delar från det här området lägger FCC till din personliga rekommendation i länken.',
    'dashboard.tutorials.blog_referral.article_step_2_title' => 'Se hur systemet fungerar',
    'dashboard.tutorials.blog_referral.article_step_2_text' => 'Om du klickar på Så här fungerar det öppnas en kort förklaring om att rekommendationen läggs till automatiskt och att besöket fortfarande är kopplat till ditt konto.',
    'dashboard.tutorials.blog_referral.article_step_3_title' => 'Dela artikeln med de färdiga knapparna',
    'dashboard.tutorials.blog_referral.article_step_3_text' => 'Här kan du direkt dela artikeln på sociala medier eller skicka den i ett meddelande. Alla alternativ använder samma länk med din rekommendation.',
