    'dashboard.tour.step_guide_text' => 'På varje viktig FCC-sida finns guiden i det övre högra hörnet. Klicka på den knappen när du vill ha korta instruktioner steg för steg för sidan du visar just nu.',
    'dashboard.tour.step_sidebar_title' => 'FCC-menyn och arbetsytor',
    'dashboard.tour.step_sidebar_text' => 'Det här är huvudmenyn för FCC i ditt användarsystem. Härifrån öppnar du kontrollpanelen, appar, din utvecklingsplan, resultat, utbildningsmaterial och produktinnehåll som stöder din dagliga Forever-verksamhet.',
    'dashboard.tour.step_menu_apps_title' => 'FCC-appar',
    'dashboard.tour.step_menu_apps_text' => 'Här öppnar du dina Forever Card-appar. De är din personliga digitala bas för att vägleda besökare till produkter, registreringar, kontakter och andra viktiga åtgärder.',
    'dashboard.tour.step_menu_ai_plan_title' => 'AI-tillväxtplan',
    'dashboard.tour.step_menu_ai_plan_text' => 'Här öppnar du din utvecklingsplan och följer den. AI använder signaler från dina appar, blogginnehåll och klick i webbshoppen för att föreslå de bästa nästa stegen för de kommande dagarna.',
    'dashboard.tour.step_menu_results_title' => 'FCC-resultat',
    'dashboard.tour.step_menu_results_text' => 'Här kan du se om systemet verkligen ger resultat. I det här området kan du följa klick, framsteg och signaler som visar vad det är värt att förstärka.',
    'dashboard.tour.step_menu_education_title' => 'Forever-utbildning',
    'dashboard.tour.step_menu_education_text' => 'Här finns videoutbildningar och förklaringar som hjälper dig att förstå systemet, följa stegen och tillämpa det du lär dig i det dagliga arbetet.',
    'dashboard.tour.step_menu_products_title' => 'Forever-produkter',
    'dashboard.tour.step_menu_products_text' => 'Här öppnas produktartiklar och rekommendationsinnehåll. Det är en av de viktigaste platserna där du kan dela innehåll med personer du rekommenderar produkter till och väcka potentiella kunders intresse för Forever-webbutiken.',
    'dashboard.tour.step_navbar_title' => 'FCC-huvudmeny',
    'dashboard.tour.step_navbar_text' => 'Toppmenyn är din huvudsakliga navigering till utbildning, produkter, blogginnehåll, kontakter och tillbaka till kontrollpanelen. Det är här förståelsen för hela FCC-systemet börjar.',
    'dashboard.tour.step_menu_forever_club_title' => 'Forever Card Club',
    'dashboard.tour.step_menu_forever_club_text' => 'Här hittar du den centrala informationen om FCC, förklaringar av systemet och innehåll som hjälper dig förstå hur appar, rekommendationer och verktyg samverkar för att bygga upp en Forever-verksamhet.',
    'dashboard.tour.step_menu_forever_products_title' => 'Forever-produkter',
    'dashboard.tour.step_menu_forever_products_text' => 'Här hittar du produktinnehåll och artiklar som du kan dela tillsammans med din rekommendation. Det är en viktig del av att väcka intresse och leda besökare till Forever-webbutiken.',
    'dashboard.tour.step_menu_blog_title' => 'Blogg',
    'dashboard.tour.step_menu_blog_text' => 'Bloggen ger dig bredare utbildningsinnehåll och affärsinnehåll som du kan använda i inlägg och meddelanden, och för att bygga förtroende med hjälp av värdefullt innehåll, inte bara genom direktförsäljning.',
    'dashboard.tour.step_menu_contact_title' => 'Kontakt',
    'dashboard.tour.step_menu_contact_text' => 'Här kan du få kontakt och support om du har fler frågor. Om något är oklart eller du behöver vägledning är det här en av platserna där du kan be om hjälp.',
    'dashboard.tour.step_menu_dashboard_title' => 'Gå till kontrollpanelen',
    'dashboard.tour.step_menu_dashboard_text' => 'Instrumentpanelen är ditt kommandocenter. Här följer du dina signaler, lär dig genom guider, ser vad som fungerar och bestämmer vad nästa steg ska vara.',
    'dashboard.tour.step_hero_title' => 'Startsidan för ditt FCC-arbete',
    'dashboard.tour.step_hero_text' => 'Det här avsnittet högst upp sammanfattar var du befinner dig just nu, vad du fokuserar på och vilka som är de snabbaste vägarna till appar, support och utbildningsguider.',
    'dashboard.tour.step_growth_title' => 'Signal och upplåsningar',
    'dashboard.tour.step_growth_text' => 'Här kan du se hur mycket faktisk aktivitet som leder till Forever Livings webbutik via din FCC-app, blogg och andra verktyg. Den signalen påverkar takten på AI-hjälpen och nästa upplåsningar i din utvecklingsplan.',
    'dashboard.tour.step_tutorials_title' => 'Minikurser och utbildning',
    'dashboard.tour.step_tutorials_text' => 'Här hittar du korta, praktiska guider för specifika uppgifter. Så fungerar FCC-utbildningen i praktiken, inte bara genom teori utan också genom små steg som du kan använda direkt.',
    'dashboard.tour.step_workbench_title' => 'Arbetsyta',
    'dashboard.tour.step_workbench_text' => 'Här ser du direkt vad som fungerar, var resultatet brister och vilka delar av systemet som redan väcker intresse. Det hjälper dig att fatta beslut utifrån verkliga signaler, inte gissningar.',
    'dashboard.tour.step_chart_title' => 'Klick som skapar resultat',
    'dashboard.tour.step_chart_text' => 'Diagrammet skiljer mellan app → Forever, blogg → Forever, registreringar och kontakter från tratten och AI-chatten. På så sätt ser du tydligt vilken del av systemet som skapar verkliga affärssignaler.',
    'dashboard.tour.step_next_action_title' => 'Ditt nästa steg',
    'dashboard.tour.step_next_action_text' => 'Det här blocket ger dig en tydlig rekommendation om vad du ska göra nu. Målet med FCC är inte att överösa dig med data, utan att hjälpa dig att välja det mest användbara nästa steget.',
    'dashboard.tour.step_support_title' => 'Ämnen för support och webbinarier',
    'dashboard.tour.step_support_text' => 'Här kan du öppna supportärenden, läsa administratörernas svar och föreslå ämnen som du vill att vi tar upp på webbinarier. Det är en del av FCC-utbildningen som hjälper dig när du kör fast eller vill få en djupare förståelse.',
