    'index.presentation1.header' => 'Forever Card App',
    'index.presentation1.subheader' => 'Varje partner får en personlig app som hen själv styr över. Den innehåller video, produkter, en AI-rådgivare, beställning utan registrering och alla verktyg för att bygga upp verksamheten.',
