    'index.presentation4.header' => 'Analys och resultatuppföljning',
    'index.presentation4.subheader' => 'Partners ser vad som fungerar, till exempel klick, intresse och besökarnas beteende, och anpassar sitt arbetssätt.',
    'index.presentation4.feature1' => 'Appvisningar och klick',
    'index.presentation4.feature2' => 'De främsta trafikkällorna',
