    'index.presentation5.header' => 'Gör intresse till verkliga affärer',
    'index.presentation5.subheader' => 'Med FCC Funnel kan du samla in kontakter enklare, följa upp snabbare och tydligt se vad som ger dig flest förfrågningar, potentiella kunder och nya teammedlemmar.',
    'index.presentation5.feature1' => 'Enklare insamling av intresserade kontakter',
