    'index.presentation6.header' => 'AI-assistenter för produktrekommendationer',
    'index.presentation6.subheader' => 'Smarta AI-assistenter hjälper människor att snabbt hitta Forever-produkter till sig själva, sina familjer och sina husdjur, samtidigt som de skapar fler samtal och försäljningsmöjligheter för dig.',
