    'index.pixels.header' => 'Avancerad analys och resultatuppföljning',
    'index.pixels.subheader' => 'Alla smarta länkar och Forever Card-appen integreras med ledande analys- och annonsplattformar.',
    'index.pixels.note' => 'Spårningsdata hjälper partners att förstå vad som fungerar, vilket innehåll som väcker intresse, var besökarna kommer ifrån och vilka kampanjer som ger resultat. Systemet stöder integrering med ledande pixel- och spårningsleverantörer.',
    'index.pricing.header' => 'Enkel och transparent prissättning.',
    'index.testimonials.one.text' => 'Den här plattformen förändrade helt vårt sätt att hantera arbetsflöden. Den är intuitiv och snabb och har sparat vårt team otaliga timmar varje vecka.',
    'index.testimonials.one.attribute' => 'Redaktör, Writer\'s Weekly',
    'index.testimonials.two.text' => 'Jag var skeptisk i början, men redan efter några dagar såg jag hur mycket mer produktivt vårt team blev. Supportteamet svarar också otroligt snabbt.',
    'index.partners.header' => 'Därför använder partners Forever Card Club',
    'index.partners.subheader' => 'Ett strukturerat digitalt system för att bygga upp en professionell och global Forever-verksamhet.',
    'index.partners.card1.title' => 'Ett system, allt på ett ställe',
    'index.partners.card1.text' => 'Personlig app, smarta länkar, utbildning, AI-stöd och analys samlade i ett enda digitalt ekosystem.',
    'index.partners.card2.title' => 'Global routing utan krångel',
    'index.partners.card2.text' => 'Smarta länkar känner automatiskt av besökarens land och leder personen till den officiella Forever-webbshoppen i sin region.',
    'index.partners.card3.title' => 'Professionell närvaro online och offline',
    'index.partners.card3.text' => 'Den personliga appen och NFC-kortet gör det enkelt att dela utan tekniska kunskaper.',
    'index.partners.card4.title' => 'Tydlig struktur för tillväxt',
    'index.partners.card4.text' => 'Programmet Min resa med 90 praktiska steg och utbildning steg för steg hjälper partner att bygga ett stabilt och långsiktigt system.',
    'index.faq.header' => 'Svar på vanliga frågor',
    'index.faq.one.question' => 'Hur får jag Forever Card-appen?',
    'index.faq.one.answer' => 'Du får din Forever Card App när du blir registrerad Forever-affärspartner och din sponsor tillhör vårt team. När du har fått åtkomst följer du en enkel introduktionsprocess som visar hur du aktiverar och ställer in din personliga app. Appen är din digitala bas. Du väljer vilka block som ska visas, till exempel video, produkter, AI-rådgivare, kontakt och utbildning, och du kan ställa in allt utan tekniska kunskaper. Om du också arbetar offline får du ett gratis NFC-kort levererat hem till dig. Med en snabb tryckning eller skanning öppnas din app.',
    'index.faq.two.question' => 'Hur fungerar beställning utan registrering och rekommendationer?',
    'index.faq.two.answer' => 'Forever Card Club använder smarta hänvisningslänkar som är utformade för att delas globalt. När en besökare klickar på din länk eller väljer en produkt i appen och väljer ”beställ” kan systemet automatiskt upptäcka besökarens land och länka vidare till den officiella Forever-webbutiken i landet. Din hänvisning är inbyggd i länken, så köpet kan kopplas till dig som rekommenderande partner, i enlighet med det officiella systemets regler. Viktigt: Forever Card Club säljer inte produkter. Alla köp genomförs via den officiella webbutiken i kundens land.',
    'index.faq.three.question' => 'Vad får jag som teammedlem?',
    'index.faq.three.answer' => 'Som teammedlem får du ett komplett system för att bygga upp en Forever-verksamhet online, inklusive: en personlig Forever Card-app, där du har dina verktyg och ditt innehåll samlade på ett ställe, smarta hänvisningslänkar som leder vidare till den officiella webbutiken i olika länder, en AI-rådgivare i appen som ger produktvägledning och information, utbildning steg för steg om hur du använder systemet och bygger upp verksamheten online, programmet Min resa med 90 praktiska steg och stöd från din sponsor, analysverktyg som visar vad personer klickar på, varifrån de kommer och vad som fungerar bäst, samt ett kostnadsfritt NFC-kort som skickas hem till dig för kontakter offline. Du får också stöd från en community, till exempel WhatsApp-grupper och tydliga riktlinjer, som hjälper dig att hålla i gång och bygga långsiktiga resultat.',
    'index.faq.four.question' => 'Hur fungerar programmet Min resa?',
    'index.faq.four.answer' => 'Min resa är ett program med 90 praktiska steg under 90 dagar. Det tar dig från att ställa in ditt kort och dina verktyg, via de första kundsamtalen och en jämn rytm för inlägg, till att hjälpa andra och starta ditt eget team. Varje dag får du ett tydligt steg på cirka 20 minuter, med ett exempelmeddelande och en fråga till din sponsor. De första 7 stegen öppnas direkt efter att du har registrerat dig hos FCC. Dina framsteg beror på din egen aktivitet, och din sponsor och Coach hjälper dig att hålla rytmen.',
    'index.faq.five.question' => 'Vad gör AI-rådgivaren i appen?',
    'index.faq.five.answer' => 'AI-rådgivaren hjälper besökare att hitta rätt information på ett enklare sätt. Utifrån deras frågor kan den föreslå relevant information och produkter och sedan guida dem till nästa steg, till exempel att läsa mer, ta kontakt eller beställa. Om besökaren väljer att beställa kan AI-rådgivaren hänvisa till den officiella webbutiken med smarta länkar som är kopplade till partnerns hänvisning. För partner innebär det mindre behov av att upprepa grundläggande information och hjälper till att hålla kommunikationen tydlig och enhetlig.',
    'index.faq.contact_note' => 'Om du vill ha åtkomst eller har en fråga kan du kontakta oss via %s.',
    'index.faq.contact_link' => 'Kontaktsida',
