    'qr_codes.breadcrumb' => 'QR-koder',
    'qr_codes.header' => 'QR-koder',
    'qr_codes.subheader' => 'Skapa enkelt anpassningsbara QR-koder och spara dem för senare bruk.',
    'qr_codes.page_intro' => 'Skapa fristående QR-koder för utskrift, delning offline, evenemang, produkter, Wi-Fi, delning av kontaktuppgifter och många andra användningsområden. Varje Forever Card App kan också skapa en egen direkt QR-kod, medan den här sektionen ger dig en separat arbetsyta där du kan skapa och redigera QR-koder på ett och samma ställe.',
    'qr_codes.guide_title' => 'En separat QR-arbetsyta för utskrifter, delning offline och kontrollerade användningsområden',
    'qr_codes.guide_text' => 'Det här QR-avsnittet är till för fristående QR-koder som du vill hantera utanför en viss appskärm. Använd det när du behöver utskrivbara QR-koder, återanvändbara kampanjkoder, åtkomstpunkter för evenemang eller produkter, eller en QR-kod med egen utformning och egna exportinställningar.',
    'qr_codes.guide_card_1_title' => 'Separat från appens QR-kod',
    'qr_codes.guide_card_1_text' => 'Varje Forever Card App kan skapa sin egen direkta QR-kod, men här kan du skapa helt separata QR-koder för andra landningssidor, länkar, material och kampanjer.',
    'qr_codes.guide_card_2_title' => 'Utformad för utskrift och användning offline',
    'qr_codes.guide_card_2_text' => 'De här QR-koderna passar utmärkt på flygblad, visitkort, affischer, produktblad, eventbord och förpackningar, samt när du delar information personligen och vill att folk skannar i stället för att skriva in uppgifterna.',
    'qr_codes.guide_card_3_title' => 'Anpassa och exportera på rätt sätt',
    'qr_codes.guide_card_3_text' => 'Styr QR-typ, stil, färger, ramar, logotyp, varumärkesprofilering och filformat så att den färdiga koden passar sammanhanget där den ska användas.',
    'qr_codes.guide_card_4_title' => 'Redigera och återanvänd senare',
    'qr_codes.guide_card_4_text' => 'När en QR-kod har skapats finns den kvar och kan laddas ner, skrivas ut, dupliceras och finjusteras senare utan att du behöver skapa den på nytt från grunden.',
    'qr_codes.empty_title' => 'Skapa din första QR-kod',
    'qr_codes.empty_text' => 'Börja med en fristående QR-kod för en länk, app, kontakt, ett evenemang eller tryckt material. När den har skapats kan du återvända och redigera stil, ram, varumärkesprofil och exportformat.',
    'qr_codes.tour.create_title' => 'Skapa en fristående QR-kod',
    'qr_codes.tour.create_text' => 'Använd den här knappen när du vill ha en QR-kod som inte är knuten till en enskild sida i Forever Card App. Den passar perfekt för kampanjer, trycksaker, evenemang och återanvändbar delning offline.',
    'qr_codes.tour.guide_title' => 'Förstå när det här avsnittet är rätt plats',
    'qr_codes.tour.guide_text' => 'Den här guiden förklarar skillnaden mellan appspecifika QR-koder och fristående QR-material. Målet är att hjälpa användare att välja rätt flöde innan de skapar eller redigerar.',
    'qr_codes.tour.list_title' => 'Ditt QR-bibliotek hålls organiserat här',
    'qr_codes.tour.list_text' => 'Den här listan blir kontrollcentralen för varje fristående QR-kod. Förhandsvisning, namn, typ, projektkoppling, exportalternativ och redigeringsbehörighet finns samlade här.',
    'qr_codes.tour.row_title' => 'Varje rad är en QR-resurs som kan återanvändas',
    'qr_codes.tour.row_text' => 'En QR-kod här kan leda till en URL, applänk, ett evenemang, WiFi-anslutning, vCard, betalningsförfrågan eller många andra typer av skanningsupplevelser. Du kan fortsätta att förfina samma tillgång över tid.',
