    'qr_codes.editor.hero_title' => 'Gör en enkel QR-kod till en återanvändbar åtkomstpunkt från offline till digitalt',
    'qr_codes.editor.hero_text' => 'Med den här redigeraren blir en QR-kod praktisk, varumärkesanpassad och redo att användas. Alla Forever Card App kan skapa en egen QR-kod, men här kan du separat skapa och finslipa QR-koder för tryck, kampanjer, evenemang, produktresor, delning av kontaktuppgifter och många andra skanningsscenarier.',
    'qr_codes.editor.hero_card_1_title' => 'Välj resultatet av skanningen',
    'qr_codes.editor.hero_card_1_text' => 'Bestäm om QR-koden ska öppna en URL, ett kontaktkort, ett betalningsflöde, en WiFi-anslutning, ett meddelandeutkast, ett evenemang, en plats eller någon annan åtgärd som stöds.',
    'qr_codes.editor.hero_card_2_title' => 'Anpassa utformningen efter sammanhanget',
    'qr_codes.editor.hero_card_2_text' => 'Anpassa stil, färger, ram, profilering och eventuell logotyp så att QR-koden passar en flyer, ett visitkort, ett produktblad, en presentation eller material för ett evenemang.',
    'qr_codes.editor.hero_card_3_title' => 'Förhandsgranska före utskrift',
    'qr_codes.editor.hero_card_3_text' => 'Använd liveförhandsvisningen, läsbarhetskontrollen och nedladdningsalternativen för att testa innan QR-koden trycks eller sprids offentligt.',
    'qr_codes.editor.hero_card_4_title' => 'Återanvänd i stället för att skapa på nytt',
    'qr_codes.editor.hero_card_4_text' => 'När en QR-kod fungerar bra kan du fortsätta att redigera, duplicera eller exportera den för nya kampanjer i stället för att börja om varje gång.',
    'qr_codes.editor.tour.intro_title' => 'Översikt över QR-redigeraren',
    'qr_codes.editor.tour.intro_text' => 'På den här sidan kan du skapa eller finslipa en fristående QR-kod som kan skrivas ut, delas, exporteras och återanvändas i många olika sammanhang.',
    'qr_codes.editor.tour.type_title' => 'Välj vad skanningen ska göra',
    'qr_codes.editor.tour.type_text' => 'QR-typen avgör vad som händer när någon skannar koden: öppna en länk, spara kontaktuppgifter, starta ett meddelande, ansluta till wifi, visa en betalningsbegäran med mera.',
    'qr_codes.editor.tour.basics_title' => 'Börja med namn och grundläggande uppgifter',
    'qr_codes.editor.tour.basics_text' => 'Ge QR-koden ett tydligt internt namn och fyll i de viktigaste innehållsfälten. Det här är innehållet som bäddas in i koden.',
    'qr_codes.editor.tour.style_title' => 'Utforma själva QR-mönstret',
    'qr_codes.editor.tour.style_text' => 'Stilen styr QR-kodens modulers och ögons geometri. Det är användbart när QR-koden visuellt ska matcha ett varumärke, en kampanj eller ett tryckt material.',
    'qr_codes.editor.tour.colors_title' => 'Justera kontrast och skanningsskärpa',
    'qr_codes.editor.tour.colors_text' => 'Färger är inte bara en estetisk fråga. God kontrast är avgörande för att koden ska gå att läsa tillförlitligt, särskilt när QR-koden skrivs ut eller visas i dålig belysning.',
    'qr_codes.editor.tour.frame_title' => 'Lägg till sammanhang kring QR-koden',
    'qr_codes.editor.tour.frame_text' => 'Ramar gör att en QR-kod ser mer genomtänkt ut och kan innehålla en uppmaning eller etikett, så att människor direkt förstår varför de ska skanna den.',
    'qr_codes.editor.tour.branding_title' => 'Lägg till logotyp och varumärkesprofilering med omsorg',
    'qr_codes.editor.tour.branding_text' => 'Med varumärkesalternativen kan du lägga in logotyper och bilder i QR-koden, men de bör testas noggrant så att den förblir lätt att läsa.',
    'qr_codes.editor.tour.options_title' => 'Slutför de tekniska inställningarna',
    'qr_codes.editor.tour.options_text' => 'Storlek, marginal, kodning, felkorrigering och projektorganisation bidrar till att QR-koden fungerar som den ska vid export och användning i produktion.',
    'qr_codes.editor.tour.preview_title' => 'Se den slutliga QR-koden i realtid',
    'qr_codes.editor.tour.preview_text' => 'I förhandsgranskningen ser du till att QR-koden fortfarande är tydlig och skanningsbar innan du laddar ner, skriver ut eller delar den.',
    'qr_codes.editor.tour.download_title' => 'Förbered material för utskrift eller leverans',
    'qr_codes.editor.tour.download_text' => 'Exportera som SVG, PNG, JPG eller WEBP beroende på om du behöver utskriftskvalitet, transparens, användning i presentationer eller snabb distribution.',
    'qr_codes.editor.tour.save_title' => 'Spara, testa och driftsätt',
    'qr_codes.editor.tour.save_text' => 'När du har sparat skannar du QR-koden med minst en telefon innan du använder den offentligt. Det är särskilt viktigt om ramar, övertoningar, logotyper eller tryckt material ingår.',
    'biolink_block_delete.header' => 'Ta bort block',
    'biolink_block_delete.subheader' => 'Alla data som är kopplade till FCC-blocket raderas helt. Åtgärden kan inte ångras.',
    'biolink_block_delete.success_message' => 'FCC-blocket har tagits bort.',
    'biolink_block.title' => 'FCC-block',
    'links_statistics.title' => 'Länkstatistik',
