    'link.header.subheader' => 'Forever Card App: %s',
    'link.header.short_link_subheader' => 'Inställningar för kortlänk: %s',
    'link.short_editor.hero_title' => 'Gör en enkel kortlänk till en kontrollerad omdirigering',
    'link.short_editor.hero_text' => 'Det är här en kort länk blir strategisk. Förutom alias och destination kan du lägga till schemaläggning, UTM-spårning, lösenordsskydd, applänkning, maskering, enhets- eller platsinriktning, HTTP-beteende och andra avancerade inställningar.',
    'link.short_editor.hero_card_1_title' => 'Börja med grunderna',
    'link.short_editor.hero_card_1_text' => 'Ange måladressen, välj ett kort alias och bestäm vilken domän kortlänken ska använda.',
    'link.short_editor.hero_card_2_title' => 'Bestäm hur det ska fungera',
    'link.short_editor.hero_card_2_text' => 'Styr när länken fungerar, vart den omdirigerar, vad som händer när den har gått ut och om frågeparametrar ska skickas vidare.',
    'link.short_editor.hero_card_3_title' => 'Följ upp och anpassa',
    'link.short_editor.hero_card_3_text' => 'Lägg till UTM-taggar, pixlar, cloaking-metadata och applänkar så att varje klick innehåller den kontext du behöver.',
    'link.short_editor.hero_card_4_title' => 'Skydda och optimera',
    'link.short_editor.hero_card_4_text' => 'Använd lösenord, varningar om känsligt innehåll, målgruppsinriktning och omdirigeringskoder för att anpassa varje kampanj till målgruppen.',
    'link.short_editor.form_title' => 'Det här kan du konfigurera för en kort länk',
    'link.short_editor.form_text' => 'Öppna bara de avsnitt du behöver eller följ handledningen steg för steg. Varje grupp nedan styr ett lager i upplevelsen av kortlänkar, från enkla omdirigeringar till avancerad kampanjlogik.',
    'link.short_editor.card_1_title' => 'För smidiga lanseringar',
    'link.short_editor.card_1_text' => 'Ange destination, alias, domän och omdirigeringskod så att länken fungerar precis som avsett från första delningen.',
    'link.short_editor.card_2_title' => 'För kampanjer och rapportering',
    'link.short_editor.card_2_text' => 'Lägg till UTM-värden, pixlar, rapporter och projekt så att trafiken kan mätas och grupperas på rätt sätt.',
    'link.short_editor.card_3_title' => 'För avancerat beteende',
    'link.short_editor.card_3_text' => 'Schemalägg tillgänglighet, ställ in utgångsregler, skydda åtkomsten, rikta dig till målgrupper eller dölj målsidan när det behövs.',
    'link.short_editor.tour.intro_title' => 'Översikt över redigeraren för kortlänkar',
    'link.short_editor.tour.intro_text' => 'På den här sidan samlas alla avancerade alternativ för en kortlänk. Målet är enkelt: att hjälpa människor förstå vad varje inställning ändrar innan de sparar.',
    'link.short_editor.tour.basics_title' => 'Grunderna kommer först',
    'link.short_editor.tour.basics_text' => 'Här anger du vart kortlänken ska leda, vilket alias den ska använda och vilken domän den ska ligga på. Det här är de grundläggande omdirigeringsinställningarna.',
    'link.short_editor.tour.app_linking_title' => 'Öppna mobilappar direkt',
    'link.short_editor.tour.app_linking_text' => 'App-länkning gör att länkar till destinationer som stöds öppnas i den inbyggda appen i stället för enbart i webbläsaren, vilket kan förbättra användarupplevelsen på telefoner.',
    'link.short_editor.tour.temporary_title' => 'Ange tidsregler och giltighetstid',
    'link.short_editor.tour.temporary_text' => 'Använd det här avsnittet för att schemalägga tillgänglighet, begränsa antalet klick eller bestämma vart personer ska skickas när länken har slutat gälla. Det passar perfekt för kampanjer, lanseringar och tidsbegränsade erbjudanden.',
    'link.short_editor.tour.utm_title' => 'Lägg till analyssammanhang',
    'link.short_editor.tour.utm_text' => 'UTM-parametrar hjälper analysverktyg att förstå trafikkälla, medium och kampanj. Det här är ett av de bästa ställena att standardisera namngivningen av kampanjer.',
    'link.short_editor.tour.protection_title' => 'Skydda åtkomsten vid behov',
    'link.short_editor.tour.protection_text' => 'Lösenord och varningar om känsligt innehåll är användbara när en länk inte ska vara helt öppen eller när besökarna behöver sammanhang innan de fortsätter.',
    'link.short_editor.tour.targeting_title' => 'Skicka olika målgrupper till olika destinationer',
    'link.short_editor.tour.targeting_text' => 'Med målinriktning kan en kort länk anpassas efter land, stad, enhet, operativsystem, webbläsarspråk eller rotationsregler. Det är ett kraftfullt verktyg för segmenterade kampanjer.',
    'link.short_editor.tour.cloaking_title' => 'Styr förhandsvisningen som andra ser',
    'link.short_editor.tour.cloaking_text' => 'Cloaking ändrar titeln, beskrivningen, bilden och annan metadata som visas innan omdirigeringen. Det är användbart när förhandsvisningen av en delad länk ska stämma överens med kampanjens budskap.',
    'link.short_editor.tour.http_title' => 'Välj omdirigeringstyp',
    'link.short_editor.tour.http_text' => '301, 302, 307 och 308 är inte identiska. I det här avsnittet avgörs om omdirigeringen betraktas som permanent eller tillfällig och hur webbläsare ska hantera den.',
    'link.short_editor.tour.advanced_title' => 'Avsluta med avancerade inställningar',
    'link.short_editor.tour.advanced_text' => 'Projekt, landningssidor, aviseringar, vidarebefordran av frågor och relaterade alternativ finns här, så att den korta länken passar in i ett större arbetsflöde.',
    'link.short_editor.tour.save_title' => 'Spara och testa',
    'link.short_editor.tour.save_text' => 'När du har sparat länken testar du den korta länken på dator och mobil. Kontrollera sedan statistiken för att se att omdirigeringar, attribuering och målgruppsinriktning fungerar som du förväntar dig.',
