efter en manuell granskning har din begäran om åtkomst till <strong>Forever Card Club</strong> inte godkänts och ditt konto har tagits bort från systemet. <br /><br />

<div style="padding:18px 20px;border-radius:16px;background:linear-gradient(135deg,#3b1822 0%,#24131f 100%);border:1px solid rgba(255,167,167,0.24);margin:18px 0;color:#fff4f4;">
    <div style="font-size:12px;letter-spacing:0.12em;text-transform:uppercase;color:#ffb9b9;margin-bottom:8px;">Vanligaste orsakerna / Najčešći razlozi</div>
