    'fcc_ai.platform.note_admin' => 'Tekniska detaljer finns fortfarande tillgängliga nedan i utfällbara avsnitt, medan huvudvyn hålls ren och överskådlig.',
    'fcc_ai.platform.note_user' => 'Se samlat hur AI aktiveras i appen, hur Coach fungerar och var konversationer och potentiella kunder följs upp.',
