    'fcc_ai.platform.list.coach_title' => 'FCC Coach',
    'fcc_ai.platform.list.coach_text' => 'Coach finns alltid tillgänglig i FCC, är kopplad till utvecklingsplanen och är utformad för att stötta dig med plattformen, sociala medier, kommunikation och affärsutveckling.',
    'fcc_ai.platform.list.single_ai_title' => 'En AI per app',
    'fcc_ai.platform.list.single_ai_text' => 'Bara en AI-rådgivare kan vara aktiv i en FCC-app åt gången. Om ett AI-block redan har lagts till visas en varning om du lägger till ett till.',
    'fcc_ai.platform.list.leads_title' => 'AI-kontakter',
    'fcc_ai.platform.list.leads_text' => 'AI-leads sparas i den befintliga /data-inkorgen och länkas till den aktuella konversationen.',
    'fcc_ai.guide.title' => 'Så använder du FCC AI',
    'fcc_ai.guide.subtitle' => 'De här korta guiderna förklarar vad varje AI kan göra och hur du får ut mesta möjliga av den i det dagliga arbetet.',
    'fcc_ai.guide.coach.title' => 'AI-coach',
    'fcc_ai.guide.coach.summary' => 'Stöd för FCC-arbetet, din utvecklingsplan och nästa praktiska steg.',
    'fcc_ai.guide.coach.intro' => 'FCC Coach är din personliga assistent på plattformen. Den är kopplad till din utvecklingsplan och hjälper dig att hålla fokus på det mest användbara nästa steget.',
    'fcc_ai.guide.coach.point_1' => 'Det kan hjälpa dig med planering, prioriteringar, fokus och nästa steg när du känner dig fast eller osäker på vad du ska göra härnäst.',
    'fcc_ai.guide.coach.point_2' => 'Det ger idéer till innehåll, kommunikation, sociala medier och dagliga aktiviteter som stödjer företagets tillväxt.',
    'fcc_ai.guide.coach.point_3' => 'Den vägleder dig genom Your Growth Plan och ger råd som är kopplade till det du behöver just nu.',
    'fcc_ai.guide.coach.tip' => 'Du får ut mest av det när du tydligt beskriver var du befinner dig, vad du vill uppnå och vilken typ av hjälp du behöver just nu.',
    'fcc_ai.guide.sales.title' => 'AI för försäljning, rekommendationer och affärssamarbete',
    'fcc_ai.guide.sales.summary' => 'Offentlig AI som rekommenderar produkter, använder bloggen och känner igen intresse för samarbete.',
    'fcc_ai.guide.sales.intro' => 'Den här AI:n pratar med besökare i din FCC-app, hjälper till att hitta produkter för människor eller husdjur och vägleder dem mot nästa steg, ett köp eller ett affärssamarbete.',
    'fcc_ai.guide.sales.point_1' => 'Den besvarar frågor, rekommenderar produkter och kan hänvisa besökaren till rätt FCC-bloggartikel för en djupare förklaring.',
    'fcc_ai.guide.sales.point_2' => 'Den följer besökaren genom hela flödet, från den första frågan till en fortsatt konversation på bloggen eller vidare till kontakt.',
    'fcc_ai.guide.sales.point_3' => 'Den kan samla in uppgifter från intresserade besökare och spara en kontakt så att partnern kan följa upp.',
    'fcc_ai.guide.sales.point_4' => 'Den kan identifiera affärsintresse och stötta sponsring genom att vägleda besökaren till nästa meningsfulla steg.',
    'fcc_ai.guide.sales.tip' => 'Det fungerar bäst när tonen är tydlig, reglerna är tydliga och rekommendationslogiken förklaras väl.',
    'fcc_ai.guide.settings.title' => 'Rådgivarinställningar',
    'fcc_ai.guide.settings.summary' => 'Här formar du hur den offentliga AI:n låter, svarar och vad den betonar.',
    'fcc_ai.guide.settings.intro' => 'I de offentliga inställningarna för AI-rådgivaren kan du anpassa kommunikationen så att den passar din stil, målgrupp och appens syfte.',
    'fcc_ai.guide.settings.point_1' => 'Assistentens namn och språk avgör hur AI:n presenterar sig och vilket språk den använder på ett naturligt sätt.',
    'fcc_ai.guide.settings.point_2' => 'Med tonen kan AI:n låta rådgivande, stödjande, vänlig eller mer direkt, beroende på vad du vill.',
    'fcc_ai.guide.settings.point_3' => 'Beskriv vilken stil du vill ha i personainstruktionerna: ett varmare bemötande, kortare svar, fler frågor, större fokus på produkter eller större fokus på affärer.',
    'fcc_ai.guide.settings.point_4' => 'I regler och riktlinjer anger du vad AI alltid ska nämna, vad den ska undvika och hur rekommendationer ska formuleras.',
    'fcc_ai.guide.settings.tip' => 'Korta och konkreta instruktioner brukar fungera bäst. Skriv som om du förklarar hur en skicklig rådgivare bör prata med en besökare.',
    'fcc_ai.guide.inbox.title' => 'AI-inkorg för de senaste 30 dagarna',
    'fcc_ai.guide.inbox.summary' => 'Här kan du följa samtal och leads samt finslipa kommunikationen i AI-chatten.',
    'fcc_ai.guide.inbox.intro' => 'AI-inkorgen visar hur assistenten faktiskt har pratat med riktiga användare. Det är den bästa platsen för att följa kvaliteten och fortsätta förbättra assistenten.',
    'fcc_ai.guide.inbox.point_1' => 'Öppna konversationer och granska var AI:n svarade bra och var svaret kunde ha varit tydligare eller mer användbart.',
    'fcc_ai.guide.inbox.point_2' => 'Håll koll på vilka frågor som återkommer ofta så att du kan förbättra tonen, personainstruktionerna och reglerna.',
    'fcc_ai.guide.inbox.point_3' => 'Om användarna fortsätter att be om fler förklaringar kan du korta ner svaren, lägga till tydligare steg eller hänvisa dem bättre till bloggen eller kontaktsidan.',
    'fcc_ai.guide.inbox.point_4' => 'Följ upp leads som AI tar in och använd informationen för att förstå var chatten hjälper mest med försäljning och sponsring.',
    'fcc_ai.guide.inbox.tip' => 'Om du märker samma problem mer än en gång bör du justera rådgivarens inställningar direkt. Små ändringar av ton och regler kan ofta göra stor skillnad.',
